<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageRetriesVO;

trait MessageRetriesAttributeHolder
{
    protected MessageRetriesVO|int|null $retries = null;
    protected bool $retriesAssigned = false;

    public function getRetriesOrDefault(MessageRetriesVO $retries): MessageRetriesVO
    {
        if ($this->retriesAssigned) {
            \assert(null !== $this->retries);
            return MessageRetriesVO::from($this->retries);
        } else {
            return $retries;
        }
    }
    public function retries(MessageRetriesVO|int $retries): static
    {
        $this->retries = $retries;
        $this->retriesAssigned = true;
        return $this;
    }
    public function getRetries(): ?int
    {
        return $this->retries instanceof MessageRetriesVO ? $this->retries->value() : $this->retries;
    }
    public function isRetriesAssigned(): bool
    {
        return $this->retriesAssigned;
    }
    public function writeRetriesTo(mixed $att): void
    {
        if ($this->retriesAssigned) {
            \assert(null !== $this->retries);
            $att->retries($this->retries);
        }
    }
    public function readRetriesFrom(mixed $att): void
    {
        if ($att->isRetriesAssigned()) {
            $retries = $att->getRetries();
            \assert(null !== $retries);
            $this->retries($retries);
        }
    }
    public function unsetRetries(): static
    {
        $this->retriesAssigned = false;
        return $this;
    }
    protected function withDefaultRetries(): void
    {
    }
    protected function withAssertedRetriesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->retriesAssigned = $this->retriesAssigned) {
            $value->retries = MessageRetriesVO::tryFrom($this->retries, $errorsList);
        }
    }
}
